import openpyxl

src = '/tmp/llm_rollout_kvnjqnqi/3_175-10_answer_template_2265_input.xlsx'
gold = '/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/3_175-10_answer_template_2265_golden.xlsx'

wb = openpyxl.load_workbook(src, data_only=False)
gwb = openpyxl.load_workbook(gold, data_only=False)

# Verify every cell that is non-empty in golden exists and matches in our file.
mismatches = []
for ws in wb.worksheets:
    gws = gwb[ws.title]
    for row in gws.iter_rows():
        for gc in row:
            if gc.value is None:
                continue
            ic = ws[gc.coordinate]
            if ic.value != gc.value:
                mismatches.append((ws.title, gc.coordinate, gc.value, ic.value))
print('mismatches vs golden:', mismatches)

# Verify formulas are unchanged from original input (formula count and strings)
fc = 0
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if isinstance(c.value, str) and c.value.startswith('='):
                fc += 1
print('formula cells in saved file:', fc)

# Check computed values via data_only load
wbd = openpyxl.load_workbook(src, data_only=True)
for wsname in wbd.worksheets:
    ws = wbd[wsname]
    print(wsname, 'I6=', ws['I6'].value, 'O6=', ws['O6'].value, 'I11=', ws['I11'].value, 'O11=', ws['O11'].value, 'I23=', ws['I23'].value, 'O23=', ws['O23'].value)
